fast_pseudocode:
# CORRECT: grid adapts to autotuned XBLOCK
@triton.autotune(configs=[Config({'XBLOCK': 1024}, ...)], key=['xnumel'])
@triton.jit
def kernel(..., XBLOCK: tl.constexpr): ...

grid = lambda meta: (triton.cdiv(xnumel, meta['XBLOCK']),)  # adapts to selected config
kernel[grid](..., xnumel)
